import { Prisma } from '@prisma/client';
import type { FastifyPluginAsync } from 'fastify';

import { hashPassword, validatePasswordPolicy, verifyPassword } from '../auth/password.js';
import { signToken } from '../auth/jwt.js';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { toUserResponse } from '../serializers/index.js';

/** 바디에서 `user.<field>`를 꺼낸다. 형식 검증은 호출자가 한다. */
function pick(body: unknown, field: string): unknown {
  if (typeof body !== 'object' || body === null) return undefined;
  const user = (body as Record<string, unknown>).user;
  if (typeof user !== 'object' || user === null) return undefined;
  return (user as Record<string, unknown>)[field];
}

/** 문자열이 아니거나 트림 후 빈 값인 필드를 모아 422로 던진다. */
function requireNonBlank(body: unknown, fields: string[]): string[] {
  const values: string[] = [];
  const blanks: string[] = [];

  for (const field of fields) {
    const value = pick(body, field);
    if (typeof value !== 'string' || value.trim() === '') {
      blanks.push(field);
      values.push('');
    } else {
      values.push(value);
    }
  }

  if (blanks.length > 0) throw ApiError.blank(...blanks);
  return values;
}

/** Prisma 유니크 제약 위반(P2002)을 409로 매핑한다. 경합으로 사전 검사를 통과한 경우. */
function conflictFrom(err: unknown): ApiError | null {
